mapper.sql:
(
    NOT EXISTS (
        SELECT 1
        FROM community_article_access ac
        WHERE ac.news_id = n.id AND ac.visibility <> 'PUBLIC'
    )
    OR (
        SELECT va.author_user_id FROM community_article va WHERE va.news_id = n.id
    ) = #{viewer}
    OR EXISTS (
        SELECT 1
        FROM community_article_access ac
        JOIN community_article_reader ar ON ar.news_id = ac.news_id
        WHERE ac.news_id = n.id
          AND ac.visibility = 'FRIENDS'
          AND ar.user_id = #{viewer}
          AND EXISTS (
              SELECT 1
              FROM community_follow f
              WHERE f.follower_id = #{viewer}
                AND f.target_key = CONCAT('u', (
                    SELECT va.author_user_id FROM community_article va WHERE va.news_id = n.id
                ))
                AND f.following = 1
          )
          AND EXISTS (
              SELECT 1
              FROM community_follow f
              WHERE f.follower_id = (
                  SELECT va.author_user_id FROM community_article va WHERE va.news_id = n.id
              )
                AND f.target_key = CONCAT('u', #{viewer})
                AND f.following = 1
          )
    )
)
AND NOT EXISTS (
    SELECT 1 FROM community_article_hidden ah
    WHERE ah.news_id = n.id AND ah.user_id = #{viewer}
)

choose.when:
COALESCE(( SELECT SUM( CASE rt.id
WHEN #{interest.tagId} THEN #{interest.weight}
ELSE 0 END ) / NULLIF(SQRT(COUNT(*)), 0) FROM community_article_tag rat JOIN community_tag rt ON rt.id = rat.tag_id WHERE rat.news_id = n.id AND rt.enabled = 1 ), 0)

mapper.sql:
CASE WHEN EXISTS (
    SELECT 1
    FROM community_follow rf
    WHERE rf.follower_id = #{query.viewer}
      AND rf.following = 1
      AND (
          rf.target_key = CONCAT('u', a.author_user_id)
          OR rf.target_key = CONCAT('b', n.blogger_id)
          OR rf.target_key = CONCAT('u', (
              SELECT rb.user_id FROM community_blogger rb WHERE rb.id = n.blogger_id
          ))
      )
) THEN 1 ELSE 0 END
